mapper.select:
SELECT r.id AS report_id, r.report_type, r.target_id, r.reason_type, r.remark, r.status, r.create_time, CASE WHEN r.report_type = 1 THEN n.title ELSE (SELECT n2.title FROM news n2 WHERE n2.id = cm.news_id) END AS target_title, CASE WHEN r.report_type = 1 THEN LEFT(n.content, 200) ELSE cm.content END AS target_content, u.username AS reporter_name, CASE WHEN r.report_type = 1 THEN nu.username ELSE cu.username END AS target_user_name FROM report r LEFT JOIN news n ON r.report_type = 1 AND n.id = r.target_id LEFT JOIN comment cm ON r.report_type = 2 AND cm.id = r.target_id LEFT JOIN user u ON u.id = r.user_id LEFT JOIN user nu ON nu.id = n.user_id LEFT JOIN user cu ON cu.id = cm.user_id WHERE (r.is_deleted IS NULL OR r.is_deleted = 0)
AND r.status = #{status}
ORDER BY r.create_time DESC LIMIT #{offset}, #{limit}
